package contracts

import (
	"errors"
	"github.com/scylladb/gocql/v2"
	"net/netip"
	"testing"
)

type statefulConviction struct{ failures map[gocql.UUID]int }

func (p *statefulConviction) AddFailure(_ error, host gocql.HostSnapshot) bool {
	p.failures[host.ID]++
	return p.failures[host.ID] >= 2
}
func (p *statefulConviction) Reset(host gocql.HostSnapshot) { delete(p.failures, host.ID) }
func TestExternalConvictionImplementation(t *testing.T) {
	policy := &statefulConviction{failures: map[gocql.UUID]int{}}
	config := gocql.DefaultConfig("127.0.0.1")
	config.Conviction = policy
	host := gocql.HostSnapshot{ID: gocql.ParseUUIDMust("ed8ea335-19d6-4652-9d9a-4519c3b6eff0"), Address: netip.MustParseAddrPort("127.0.0.1:9042"), Datacenter: "dc1", Rack: "r1", Tokens: []int64{-1, 1}, Enabled: true, Up: true}
	failure := errors.New("external failure")
	if config.Conviction.AddFailure(failure, host) || !config.Conviction.AddFailure(failure, host) {
		t.Fatal("stateful conviction decision")
	}
	config.Conviction.Reset(host)
	if config.Conviction.AddFailure(failure, host) {
		t.Fatal("reset did not clear the selected host")
	}
	var simple gocql.ConvictionPolicy = &gocql.SimpleConvictionPolicy{}
	if !simple.AddFailure(failure, host) {
		t.Fatal("simple conviction behavior changed")
	}
	simple.Reset(host)
	if !simple.AddFailure(failure, host) {
		t.Fatal("simple reset behavior changed")
	}
}

